@icontract.ensure(
    lambda result, left, right, key, arr:
        (
            result != -1
            and 0 <= result < len(arr)
            and left <= result < right
            and arr[result] == key
        )
        or (
            result == -1
            and all(
                arr[i] != key
                for i in range(max(left, 0), min(right, len(arr)))
            )
        )
)
